// Enhanced Evolution API webhook normalization
const body = $input.first().json;

let event = body;
if (body.body) event = body.body;
if (body.data && typeof body.data === 'object') event = body.data;

const eventType = event.event || body.event || 'unknown';

// Only process message events
if (eventType !== 'messages.upsert' && eventType !== 'MESSAGES_UPSERT' && !eventType.includes('message')) {
  return { skip: true, reason: 'not_message_event' };
}

const data = event.data || event.message || event;
const key = data.key || data;

const messageId = key.id || data.id || data.external_id || require('crypto').randomUUID();
const remoteJid = key.remoteJid || data.remoteJid || data.from || '';
const isGroup = remoteJid.includes('@g.us');
const fromMe = key.fromMe || data.fromMe || false;

// Extract message content with support for various types
let content = '';
let messageType = 'text';
let hasMedia = false;

if (data.message?.conversation) {
  content = data.message.conversation;
  messageType = 'text';
} else if (data.message?.extendedTextMessage?.text) {
  content = data.message.extendedTextMessage.text;
  messageType = 'text';
} else if (data.message?.imageMessage) {
  content = data.message.imageMessage.caption || '[Image]';
  messageType = 'image';
  hasMedia = true;
} else if (data.message?.videoMessage) {
  content = data.message.videoMessage.caption || '[Video]';
  messageType = 'video';
  hasMedia = true;
} else if (data.message?.audioMessage) {
  content = '[Audio/Voice Note]';
  messageType = 'audio';
  hasMedia = true;
} else if (data.message?.documentMessage) {
  content = data.message.documentMessage.caption || '[Document: ' + (data.message.documentMessage.fileName || 'file') + ']';
  messageType = 'document';
  hasMedia = true;
} else if (data.body) {
  content = data.body;
  messageType = 'text';
}

// Check if mentioned me
const mentionedMe = content.toLowerCase().includes('@me') || 
                    content.toLowerCase().match(/\b(me|you)\b/i) || 
                    content.includes('@');

const timestamp = data.messageTimestamp 
  ? new Date(data.messageTimestamp * 1000).toISOString()
  : data.timestamp 
    ? new Date(data.timestamp).toISOString()
    : new Date().toISOString();

return {
  skip: false,
  external_id: messageId,
  source: 'whatsapp',
  chat_id: remoteJid,
  chat_name: data.pushName || (isGroup ? remoteJid.split('@')[0] : remoteJid.split('@')[0]),
  is_group: isGroup,
  sender_id: data.key?.participant || remoteJid,
  sender_name: data.pushName || data.senderName || '',
  message_type: messageType,
  content: content,
  has_media: hasMedia,
  mentioned_me: !!mentionedMe,
  timestamp: timestamp,
  raw_payload: event,
  from_me: fromMe,
  instance_id: data.instanceId || event.instanceId || 'default'
};

// Normalize Android notification
const body = $input.first().json;

let data = body;
if (body.body) {
  try { 
    data = typeof body.body === 'string' ? JSON.parse(body.body) : body.body; 
  } catch (e) { 
    data = body; 
  }
}

const externalId = data.external_id || `${data.app_package}_${data.post_time || Date.now()}_${Math.random().toString(36).substr(2,9)}`;

return {
  external_id: externalId,
  app_package: data.app_package || 'unknown',
  app_name: data.app_name || data.app_package || 'Unknown App',
  title: data.title || '',
  content: data.content || data.text || '',
  ticker: data.ticker || '',
  post_time: data.post_time ? new Date(data.post_time).toISOString() : new Date().toISOString(),
  is_clearable: data.is_clearable !== false,
  category: data.category || '',
  raw_payload: data
};
